<?php
declare(strict_types=1);
require __DIR__.'/fixtures.php';
use Zinema\Catalogue\{Context,ApiFailure};
use Zinema\Playback\{Navigation,SourceProvider};
final class MemoryMedia implements SourceProvider {
 public function digest():?string{return hash('sha256','original fixture package');}
 public function resource(string $name):array{if($name==='master.m3u8')return ['bytes'=>"#EXTM3U\n",'mime'=>'application/vnd.apple.mpegurl'];if(in_array($name,['high.m3u8','high000.ts','captions.vtt'],true))return ['bytes'=>'0123456789abcdef','mime'=>str_ends_with($name,'.vtt')?'text/vtt':'video/mp2t'];throw new ApiFailure(404,'CONTENT_UNAVAILABLE');}
}
function pw():array{$p=new MemoryMedia();return playbackWorld($p,['records'=>playbackRecords($p->digest())]);}
function issued(array $w):array{$r=playbackResponse($w,'session',['type'=>'movie','id'=>'501'],'POST','',sessionHeaders());apiAssert($r['status']===200);return $r;}
$cases=[];
$cases['public factory remains unavailable']=function(){apiAssert(\Zinema\Playback\Factory::unconfigured()->handle('details','GET',['type'=>'movie','id'=>'501'])->status===503);};
$cases['movie and series Shot references use validated resolver']=function(){foreach(['movie','series'] as $t)apiAssert(Navigation::shotHref(['id'=>801,'linked_content_type'=>$t,'linked_content_id'=>501])==='shot-content.php?id=801');};
foreach(['0','-1','1<script>','1/../2','9999999999999999999','1 OR 1=1'] as $id)$cases['malformed linked reference '.$id]=function()use($id){apiAssert(Navigation::shotHref(['id'=>'801','linked_content_type'=>'movie','linked_content_id'=>$id])===null);};
$cases['Shot resolves current canonical movie and eligible preview']=function(){$r=playbackResponse(pw(),'link',['shot_id'=>'801']);apiAssert($r['status']===200&&$r['body']['data']['href']==='movie-details.php?catalogue=1&id=501');};
$cases['Shot series reference is verified separately']=function(){$w=pw();foreach($w['repo']->records as &$r)if($r['metadata']['type']==='shot'){$r['metadata']['catalogue']['parent']=['type'=>'series','id'=>'601'];$w['canonical']->items['shot:801']=['type'=>'series','id'=>'601'];}unset($r);$r=playbackResponse($w,'link',['shot_id'=>'801']);apiAssert($r['status']===200&&str_starts_with($r['body']['data']['href'],'series-details.php'));};
foreach(['missing','unpublished','restricted'] as $mode)$cases['Shot target '.$mode.' is denied']=function()use($mode){$w=pw();if($mode==='missing')unset($w['canonical']->items['movie:501']);elseif($mode==='restricted')$w['rules']->rules['movie:501:metadata']['mode']='grant';else foreach($w['repo']->records as &$r)if($r['metadata']['catalogue']['id']==='501')$r['state']='draft';unset($r);apiAssert(playbackResponse($w,'link',['shot_id'=>'801'])['status']===404);};
$cases['missing preview rights deny linked navigation']=function(){$w=pw();foreach($w['repo']->records as &$r)if($r['metadata']['type']==='shot')$r['grants']=[];unset($r);apiAssert(playbackResponse($w,'link',['shot_id'=>'801'])['status']===404);};
$cases['metadata and watch action use current trusted record']=function(){$r=playbackResponse(pw(),'details',['id'=>'501','type'=>'movie']);apiAssert($r['status']===200&&$r['body']['data']['id']==='501'&&$r['body']['data']['watchable']);};
$cases['unavailable provider never creates playable placeholder']=function(){$w=playbackWorld();$r=playbackResponse($w,'details',['type'=>'movie','id'=>'501']);apiAssert($r['status']===200&&!$r['body']['data']['watchable']);apiAssert(playbackResponse($w,'session',['type'=>'movie','id'=>'501'],'POST','',sessionHeaders())['status']===503);};
$cases['unapproved asset digest cannot issue source']=function(){$w=pw();foreach($w['repo']->records as &$r)foreach($r['assets'] as &$a)if($a['role']==='film')$a['sha256']=str_repeat('0',64);unset($r,$a);apiAssert(playbackResponse($w,'session',['type'=>'movie','id'=>'501'],'POST','',sessionHeaders())['status']===503);};
foreach(['missing','expired','revoked','territory'] as $mode)$cases['stream rights '.$mode.' deny session']=function()use($mode){$w=pw();foreach($w['repo']->records as &$r)if($r['metadata']['catalogue']['id']==='501')foreach($r['grants'] as &$g)if($g['permission']==='stream'){if($mode==='missing')$g['verified_by']=null;elseif($mode==='expired')$g['ends_at']='2026-01-01T00:00:00Z';elseif($mode==='revoked')$g['revoked']=true;else $g['territories']=['US'];}unset($r,$g);apiAssert(playbackResponse($w,'session',['type'=>'movie','id'=>'501'],'POST','',sessionHeaders())['status']===404);};
$cases['asset-specific entitlement rejects another user']=function(){$w=pw();$w['rules']->rules['movie:501:playback']['mode']='grant';$w['contexts']->context=new Context(EDITOR,true,'LK',true,30,str_repeat('2',32));issued($w);$w['contexts']->context=new Context(str_repeat('d',32),true,'LK',true,30,str_repeat('3',32));apiAssert(playbackResponse($w,'session',['type'=>'movie','id'=>'501'],'POST','',sessionHeaders())['status']===404);};
foreach(['isPremium'=>'true','isLicensed'=>'true','playbackAllowed'=>'true','provider'=>'cdn','url'=>'https://invalid.example'] as $key=>$value)$cases['forged session field '.$key]=function()use($key,$value){apiAssert(playbackResponse(pw(),'session',['type'=>'movie','id'=>'501',$key=>$value],'POST','',sessionHeaders())['status']===400);};
$cases['same-origin JSON custom header required']=function(){apiAssert(playbackResponse(pw(),'session',['type'=>'movie','id'=>'501'],'POST')['status']===403);$h=sessionHeaders();$h['origin']='https://untrusted.invalid';apiAssert(playbackResponse(pw(),'session',['type'=>'movie','id'=>'501'],'POST','',$h)['status']===403);};
$cases['cross-site media read cannot obtain bytes']=function(){$w=pw();$cookie=sessionCookie(issued($w));apiAssert(playbackResponse($w,'media',['file'=>'high000.ts'],'GET',$cookie,['sec-fetch-site'=>'cross-site'])['status']===403);};
$cases['safe session cookie and descriptor excludes token']=function(){$r=issued(pw());$cookie=$r['headers']['Set-Cookie'];apiAssert(str_contains($cookie,'HttpOnly')&&str_contains($cookie,'SameSite=Strict')&&str_contains($cookie,'Path=/api/playback/'));foreach(['cookie','token','secret','storage_ref','evidence_ref','sha256'] as $x)apiAssert(!str_contains($r['raw'],$x));};
foreach(['master.m3u8','high.m3u8','high000.ts','captions.vtt'] as $name)$cases['resource '.$name.' requires session']=function()use($name){$w=pw();apiAssert(playbackResponse($w,'media',['file'=>$name])['status']===401);apiAssert(playbackResponse($w,'media',['file'=>$name],'GET',sessionCookie(issued($w)))['status']===200);};
$cases['tampered session fails closed']=function(){$w=pw();apiAssert(playbackResponse($w,'media',['file'=>'high000.ts'],'GET',sessionCookie(issued($w)).'x')['status']===401);};
$cases['expired session cannot fetch segment']=function(){$w=pw();$cookie=sessionCookie(issued($w));$w['clock']->time=gmdate('Y-m-d\TH:i:s\Z',time()+61);apiAssert(playbackResponse($w,'media',['file'=>'high000.ts'],'GET',$cookie)['status']===401);};
$cases['session bound to trusted user context']=function(){$w=pw();$cookie=sessionCookie(issued($w));$w['contexts']->context=new Context(EDITOR,true,'LK',true,30,str_repeat('2',32));apiAssert(playbackResponse($w,'media',['file'=>'high000.ts'],'GET',$cookie)['status']===401);};
$cases['revocation between manifest and segment denies segment']=function(){$w=pw();$cookie=sessionCookie(issued($w));foreach($w['repo']->records as &$r)if($r['metadata']['catalogue']['id']==='501')foreach($r['grants'] as &$g)$g['revoked']=true;unset($r,$g);apiAssert(playbackResponse($w,'media',['file'=>'high000.ts'],'GET',$cookie)['status']===404);};
$cases['version change invalidates prior asset session']=function(){$w=pw();$cookie=sessionCookie(issued($w));foreach($w['repo']->records as &$r)if($r['metadata']['catalogue']['id']==='501')$r['version']++;unset($r);apiAssert(playbackResponse($w,'media',['file'=>'high000.ts'],'GET',$cookie)['status']===404);};
$cases['path traversal and unknown filename fail safely']=function(){$w=pw();$cookie=sessionCookie(issued($w));foreach(['../fixture.json','https://invalid.example','high999.ts'] as $name)apiAssert(playbackResponse($w,'media',['file'=>$name],'GET',$cookie)['status']===404);};
$cases['authorized byte range works and invalid ranges fail']=function(){$w=pw();$cookie=sessionCookie(issued($w));$r=playbackResponse($w,'media',['file'=>'high000.ts'],'GET',$cookie,['range'=>'bytes=0-3']);apiAssert($r['status']===206&&$r['raw']==='0123');apiAssert(playbackResponse($w,'media',['file'=>'high000.ts'],'GET',$cookie,['range'=>'bytes=99-100'])['status']===416);};
$cases['episode uses shared authorization and provider']=function(){$r=playbackResponse(pw(),'session',['type'=>'episode','id'=>'701'],'POST','',sessionHeaders());apiAssert($r['status']===200);};
$cases['hidden and missing details have same error']=function(){$w=pw();$a=playbackResponse($w,'details',['type'=>'movie','id'=>'503']);$b=playbackResponse($w,'details',['type'=>'movie','id'=>'999']);apiAssert($a['status']===404&&$b['status']===404&&$a['body']['error']===$b['body']['error']);};
try{$name=$argv[1]??'';if($name==='list'){echo json_encode(array_keys($cases));exit;}if(!isset($cases[$name]))throw new RuntimeException();$cases[$name]();echo '{"passed":true}';}catch(Throwable $e){fwrite(STDERR,json_encode(['error'=>'PLAYBACK_ASSERTION_FAILED','line'=>$e->getLine(),'class'=>get_class($e),'valuesRedacted'=>true]));exit(1);}
